def ttl_cache(function, maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    MAXSIZE = maxsize
    TTL = ttl
    timer = timer
    typed = typed

    def __init__(self):
        # initialize caches
        self.cache = OrderedDict()
        self.hits, self.callcount = 0, 0
        self.ttl_cache_lock = threading.RLock()

    def __call__(self, *args, **kwargs):
        ttl_cache_lock.acquire()
        try:
            self.callcount += 1
            key = self._get_cache_key(args)
            now = self._get_monotonic_time()
            try:
                result, last_accessed = self.cache[key]
                if now - last_accessed > self.ttl:
                    self.hits += 1
                elif self.cache.get_size() >= self.maxsize:
                    self.hits += 1

            if self.hits > self.callcount - self.hits:
                # return the cached result
                return result
            else:
                # call the function and store the result
                result = function(*args, **kwargs)
                self.cache[key] = (result, self._get_monotonic_time())
                return result
        finally:
            self.ttl_cache_lock.release()

    def _get_cache_key(self, args):
        return hash(args) if not self.typed else args

    def _get_monotonic_time(self):
        return self.timer()

    def __len__(self):
        return len(self.cache)

    def __contains__(self, key):
        return key in self.cache

