def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    def decorator(func):
        cache = {}
        hits, misses = 0, 0
        def wrapper(*args):
            nonlocal hits, misses
            if typed:
                key = (type(args[0]), args[0])
            else:
                key = args[0]
            if key in cache:
                hits += 1
                return cache[key]
            else:
                misses += 1
                result = func(*args)
                if len(cache) < maxsize:
                    cache[key] = result
                else:
                    cache.popitem()
                    cache[key] = result
                return result
        wrapper.hits = hits
        wrapper.misses = misses
        return wrapper
    return decorator

def lru_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = dict()
        keys = set()

        def wrapper(*args, **kwargs):
            key = (args, tuple(sorted(kwargs.items()))) if typed else args
            if key not in keys or len(keys) > maxsize:
                keys.add(key)
                cache[key] = func(*args, **kwargs)
            return cache[key]

        return wrapper

    return decorator

