def lru_cache(self, maxsize=128, typed=False):
    """Cache the last few returns of this method.

    Arguments:
        maxsize (int): The maximum number of items to cache. Defaults to 128.
        typed (bool): False if the size is measured in the number of calls. True if the size is measured in the number of arguments. Defaults to False.
    """
    # if maxsize is zero, disable caching
    if maxsize == 0:
        def wrapper(*args, **kwargs):
            return self(*args, **kwargs)
        return wrapper

    # if maxsize is one, do not use a queue
    if maxsize == 1:
        cache = []
        def wrapper(*args, **kwargs):
            cache.append((args, kwargs))
            return self(*args, **kwargs)
        return wrapper

    # use a queue to implement LRU caching
    cache = collections.deque(maxlen=maxsize)
    def wrapper(*args, **kwargs):
        key = (args, kwargs) # convert args and kwargs to a tuple for hashing
        if typed:
            key += (self.__qualname__,) # use the qualified name of this method to differentiate between different values of ____qualname____
        if key in cache:
            return cache.pop(key)
        else:
            result = self(*args, **kwargs)
            cache.append((key, result))
            return result
    return wrapper

