def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    def wrap(f):
        def wrapper(self, *args, **kwargs):
            if cache is None:
                return f(self, *args, **kwargs)
            else:
                if key is None:
                    k = f.__name__ + str(args) + str(kwargs)
                else:
                    k = key(self, *args, **kwargs)
                if lock is not None:
                    with lock:
                        if k not in cache:
                            result = f(self, *args, **kwargs)
                            cache[k] = result
                        else:
                            result = cache[k]
                else:
                    if k not in cache:
                        result = f(self, *args, **kwargs)
                        cache[k] = result
                    else:
                        result = cache[k]
                return result
        return wrapper
    return wrap
