def cachedmethod(cache, key=hashkey, lock=None):
    def decorator(func):
        if lock is None:
            lock = RLock()

        def wrapper(*args, **kwargs):
            ckey = key(*args, **kwargs)
            try:
                result = cache[ckey]
            except KeyError:
                with lock:
                    try:
                        result = cache[ckey]
                    except KeyError:
                        result = cache[ckey] = func(*args, **kwargs)
            return result
        return wrapper
    return decorator
