def _normalizeargs(sequence: Sequence[Target], output: Mapping[Parameter, Object] = None) -> List[Mapping[Parameter, TypeVar]]:
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = {}

    if not isinstance(sequence, list):
        raise TypeError('sequence must be a list')

    for entry in sequence:
        if isinstance(entry, Declaration) and entry not in output:
            output[entry] = {Parameter.of(declaration) for p in entry.parameters}

        if isinstance(entry, set):
            for el in entry:
                output[el] = {'parameter': Some(el)

        if isinstance(entry, Signature):
            output[entry] = {'interface': Some(entry)}

        if isinstance(entry, (implements, implements_for)):
            if entry.spec in output:
                output[entry.spec]['parameters'] = {Parameter.of(e): TypeVar.of(e) for e in entry.parameters}
            else:
                output[entry.spec] = {'parameters': {entry.parameters.of(p): TypeVar.of(p) for p in entry.parameters}}

    return output.values()
