def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # create a list of commands to execute
    cmds = []
    if isinstance(commands, str):
        cmds.append(commands)
    elif isinstance(commands, list):
        cmds.extend(commands)
    else:
        raise ValueError("commands must be a string or a list")

    # create a list of arguments to execute
    cmd_args = []
    if isinstance(args, str):
        cmd_args.append(args)
    elif isinstance(args, list):
        cmd_args.extend(args)
    else:
        raise ValueError("args must be a string or a list")

    # create a list of environments to use
    env_list = []
    if isinstance(env, str):
        env_list.append(env)
    elif isinstance(env, list):
        env_list.extend(env)
    else:
        raise ValueError("env must be a string or a list")

    # loop through each command and execute it
    for cmd in cmds:
        for arg in cmd_args:
            # get the full command
            full_cmd = cmd + " " + arg
            if verbose:
                print(full_cmd)

            # create a subprocess execution object
            p = subprocess.Popen(full_cmd, shell=True, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, encoding="utf-8")

            # run the command and wait for it to finish
            p.communicate("")

            # if the command raised an error, raise it
            if p.returncode != 0:
                msg = p.stdout
                if p.stderr:
                    msg += p.stderr
