def validate_version_inventories(self, version_dirs):
    for ver in version_dirs:
        inventory_path = os.path.join(ver, "inventory.json")
        if not os.path.exists(inventory_path):
            raise FileNotFoundError(f"Inventory file not found in version {ver}")
        with open(inventory_path) as inventory_file:
            for line in inventory_file:
                line = line.strip()
                if len(line) == 0:
                    continue
                if line[0] == "#":
                    continue
                if line[0] == "-":
                    continue
                parts = line.split(",")
                if len(parts) != 3:
                    raise ValueError(f"Inventory file: invalid line {line} in version {ver}")
                content_type = parts[0].strip()
                content_digest = parts[1].strip()
                if content_type not in ["file", "dir"]:
                    raise ValueError(f"Inventory file: unknown content type {content_type} in version {ver}")
                if not content_digest.startswith("content-sha256="):
                    raise ValueError(f"Inventory file: invalid content digest {content_digest} in version {ver}")
                if content_digest == "content-sha256=abcd":
                    # skip the root inventory, which has an empty content digest
                    continue
                if ver == 1:
                    raise ValueError(f"The root inventory digest should not be included in version 1 {ver}")
                if content_digest in self.cur_digests:
                    # skip the first version, which adds the root directory
                    if ver != 1:
                        self.diff_digests.append(content_digest)
                        self.diff_files.append(content_type)
                else:
                    self.cur_digests.add(content_digest)
    return self.cur_digests, self.diff_digests, self.diff_files
