def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Keep a record of content digests that are different from the root inventory
    self.different_digests = {}

    # Iterate over the version directories and validate their inventories
    for version_dir in version_dirs:
        try:
            inventory = self.load_inventory(version_dir)
        except (OSError, ValueError) as e:
            raise ValidationError("Cannot load inventory for version directory '{}': {}".format(version_dir, e))

        if not inventory:
            inventory = self.empty_inventory()

        if version_dir != "2":
            # Get the root inventory and compare it with the current inventory
            root_inventory = self.load_inventory("1")

            if not root_inventory:
                raise ValidationError("Cannot load root inventory for version directory '1'.")

            if not self.check_inventory_consistency(root_inventory, inventory):
                raise ValidationError("Inconsistent inventory for version directory '{}'.".format(version_dir))

            # Check if there are any different content digests in the current inventory
            different_digests = self.get_different_digests(root_inventory, inventory)
            self.different_digests[version_dir] = different_digests

    return self.different_digests

# Utility functions
def check_inventory_consistency(root_inventory, inventory):
    for key, value in root_inventory.items():
        if key not in inventory:
            return False

        if value != inventory[key]:
            return False

    return True

