                if not isinstance(merged_nodes[node.value], MappingNode):
                    # If it's not a MappingNode, then it's an integer or string,
                    # so we just use the last value that we see for that key
                    merged_nodes[node.value] = node
                elif isinstance(merged_nodes[node.value], MappingNode):
                    # If it is a MappingNode, then we need to recursively merge the child nodes
                    # to handle any duplicate keys that may be present
                    merged_nodes[node.value] = deep_merge_nodes([merged_nodes[node.value], node])
            else:
