    """
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    """
    import argparse
    from argparse import _ActionsContainer
    from argcomplete.completers import DirectoriesCompleter

    parser = argparse.ArgumentParser(prog='borgmatic')
    add_subparsers = parser.add_subparsers(help='sub-command help')

    for action in _ActionsContainer.direct_actions:
        if action.default and action.default != SUPPRESS:
            add_argument(action.option_strings, default=action.default)

    for subparser in add_subparsers.choices.values():
        for action in subparser._actions:
            if action.default and action.default != SUPPRESS:
                arg = action.option_strings
                if '--path' in arg:
                    arg = '--path'
                elif arg in {'-e', '--exact'}:
                    continue
                elif arg in {'-d', '--directory'}:
                    arg = '--path'
                completer = DirectoriesCompleter()
                parser.add_argument(arg, completer=completer)

    return parser.format_help()
