def paging(response, max_results):
    def __init__(self, response, max_results):
        self.response = response
        self.max_results = max_results

    def __iter__(self):
        # Yield all pages of the response
        for i in range(0, len(self.response), self.max_results):
            yield self.response[i:i + self.max_results]

    def __len__(self):
        # Return the number of pages in the response
        return int(len(self.response) / self.max_results)

