def _split_windows(s):
    """Split a string using Windows-style command-line rules."""

    # See: https://docs.microsoft.com/en-us/cpp/c-language/parsing-c-command-line-arguments

    pairs = re.split(r'\s*', s)
    args = []

    for p in pairs:
        args.extend(re.split(r'[^\S\"]*\".*?\"[^\S\"]*', p))

    return [re.sub(r'\"', '', t) for t in args]


def _split_posix(s):
    """Split a string using POSIX-style command-line rules."""

    # See: https://pubs.opengroup.org/onlinepubs/9699919799/basedefs/V1_chap02.html

    pairs = re.split(r'\s+', s)
    args = []

    for p in pairs:
        args.extend(re.split(r'(?:\G\\+|[^\s\\])+', p))

    return [re.sub(r'\\(?=\S)', '', t) for t in args]


