def run_command(commands, args=None, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, list):
        commands = [commands]

    if args is not None and not isinstance(args, list):
        args = [args]

    if cwd is not None and not isinstance(cwd, str):
        raise ValueError("'cwd' must be a string")

    if env is not None and not isinstance(env, dict):
        raise ValueError("'env' must be a dictionary")

    for command in commands:
        if not isinstance(command, str):
            raise ValueError("command must be a string")

    try:
        if env is None:
            env = os.environ
        for k, v in env.items():
            # Ensure environment variables are strings
            if not isinstance(k, str):
                raise ValueError("Found non-string key in 'env'")
            if not isinstance(v, str):
                raise ValueError("Found non-string value in 'env'")

        if args is None:
            process = subprocess.Popen([command, *commands], cwd=cwd, env=env, text=True)
        else:
            process = subprocess.Popen([command, *commands, *args], cwd=cwd, env=env, text=True)

        if not hide_stderr:
            while True:
                line = process.stdout.readline()
                if not line and process.poll() is not None:
                    break
                if verbose:
                    print(line.strip())
            return process.returncode
        else:
