def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    """Convert a histogram to a graph.

    :param hist: The histogram to convert. Must contain numeric bins or be processed by *make_value*.
    :param make_value: A function to set the value of a graph point. Leave empty for default (bin content).
    :param get_coordinate: The method to get coordinate from a histogram bin. Can be "left", "right" or "middle". Default is "left".
    :param field_names: Set of field names of the graph. Must have the same number of elements as the resulting graph's dimension. Default is ("x", "y").
    :param scale: The graph's scale. Set to the histogram's scale if True. Default is None.
    :return: The resulting graph.
    """
    if make_value is None:
        make_value = {(b.start, b.end): b.content for b in hist.bins}
    if get_coordinate == "left":
        get_coordinate = lambda b: b.start
    elif get_coordinate == "right":
        get_coordinate = lambda b: b.end
    elif get_coordinate == "middle":
        get_coordinate = lambda b: (b.start + b.end) / 2
    else:
        raise ValueError("Invalid get_coordinate option: '{}'".format(get_coordinate))
    graph = Graph(scale=scale)
    for i, bin_ in enumerate(hist.bins):
        graph.add(Point(make_value(bin_), get_coordinate(bin_), field_names=field_names))
    return graph

