def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.

    Args:
        iface (str): The interface to verify
        candidate (class): The candidate object
        tentative (bool): Optional. True if the interface is still open for definition, defaults to False

    Returns:
        bool: True if the interface is correctly provided by the candidate, False otherwise
    """

    # Verify that the interface is a documented and explicitly declared API
    if not hasattr(iface, '__is_interface'):
        raise TypeError('%s is not an interface' % iface)

    # Verify that the candidate class fully implements the interface
    for method in iface.__interface__:
        if not hasattr(candidate, method):
            raise TypeError('%s is not a correct implementation of %s' % (candidate, iface))

    # If the interface is not yet complete, then tentatively valid by default
    if tentative and not iface.__is_complete__:
        return True

    # Verify that the implementation is correct for all declared attributes
    for attribute in iface.__attributes__:
        if attribute not in candidate.__annotations__:
            raise TypeError('%s is not a valid implementation of %s' % (attribute, iface))

    # Finally, verify that all method signatures are correct
    for method in iface.__methods__:
        if not hasattr(candidate, method):
            raise TypeError('%s is not a valid implementation of %s' % (method, iface))
        elif candidate.__annotations__[method] != iface.__annotations__[method]:
            raise TypeError('%s is not a correct implementation of %s' % (method, iface))

    return True
