def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # Make sure bases is a tuple
    if not isinstance(bases, tuple):
        bases = (bases,)

    # If there's not an explicit metaclass, default to type
    if explicit_mc is None:
        return type

    # If there's an explicit metaclass, make sure it's a class
    elif not inspect.isclass(explicit_mc):
        raise TypeError("explicit_mc must be a class")

    # Make sure the explicit metaclass is a subclass of the type metaclass
    if not issubclass(explicit_mc, type):
        raise TypeError("explicit_mc must be a subclass of type")

    # Make sure the explicit metaclass is compatible with all the bases
    for base in bases:
        if not issubclass(explicit_mc, base):
            raise TypeError("explicit_mc must be a subclass of all bases")

    return explicit_mc

def determineMetaclass(bases: list, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    if explicit_mc:
        return explicit_mc
    else:
        metaclass = None
        for base in bases:
            if hasattr(base, '__metaclass__'):
                if not metaclass:
                    metaclass = base.__metaclass__
                elif metaclass != base.__metaclass__:
                    raise TypeError('Inconsistent metaclass definition in bases')
        if not metaclass:
            raise TypeError('No valid metaclass definition found in bases and explicit_mc')
        return metaclass

