        raise ValueError("fromutc() argument must be a timezone-aware datetime object")

    new_dt = dt.astimezone(self.tz)

    if self.tz.fold and new_dt.dst():
        # The datetime is ambiguous and in "fold" (e.g. DST end)
        # Determine whether the datetime is the first occurrence, chronologically,
        # of the ambiguous datetime
        transitions = self.tz.transitions
        after = None
        for transition in transitions:
            if transition.dt > dt:
                after = transition
                break

        if after:
            after_dt = after.astimezone(self.tz)
            if after_dt - dt == timedelta(hours=24):
