                tag += c
                c = text[i]
                i += 1
            tag = tag.strip()
            tags.add(tag)

            if replacer is not None:
                text = text[:i+1] + replacer(tag) + text[i+1:]
        elif c == '\n' and not code_block:
            tags.clear()

    return tags, text

