def verify_relayable_signature(public_key, doc, signature):
        """
        Verify the signed XML elements to have confidence that the claimed
        author did actually generate this message.
        """
        if not isinstance(public_key, RSA.RSAKey):
            raise ValueError("public_key must be an instance of RSA.RSAKey")
        if not isinstance(doc, etree.ElementTree):
            raise ValueError("doc must be an instance of etree.ElementTree")
        if not isinstance(signature, RSA.Signature):
            raise ValueError("signature must be an instance of RSA.Signature")

        # Check if the signature is XML-DSIg valid
        # the algorithm used by xml-dsig is "http://www.w3.org/2000/09/xmldsig#dsa-sha1" by default
        validation_algorithm = "http://www.w3.org/2000/09/xmldsig#dsa-sha1"
        try:
            signature.verify(public_key, validation_algorithm)
        except RSA.RejectedSignatureException:
            return False

        # Check if the digest of the signature is correct for the XML document
        digest_algorithm = "http://www.w3.org/2000/09/xmldsig#sha1"
        doc_digest = doc.getroot().digest(algorithm=digest_algorithm)
        if not doc_digest:
            return False
        if not signature.verify_content(doc_digest):
            return False

        return True

