def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    if not self.spec:
        raise ValueError("No spec provided")

    args = self.spec["args"]
    kwargs = {}

    for arg in args:
        default = None
        if "default" in arg:
            default = arg["default"]
        elif "default_factory" in arg:
            default = arg["default_factory"]()
        elif "alias" in arg:
            if arg["alias"] in kwargs:
                default = kwargs[arg["alias"]]
            else:
                raise ValueError("No value provided for argument {}".format(arg["alias"]))
        elif "required" in arg and arg["required"]:
            raise ValueError("No value provided for required argument {}".format(arg["name"]))

        kwargs[arg["name"]] = default

    return kwargs
